CustomField.formula:
(
    IF(
        Surest_SPD__c = 0, 0,
        IF(
            Surest_SPD__c = 1, 1,
            IF(
                Surest_SPD__c <= 5, 2,
                IF(
                    Surest_SPD__c <= 15, 3,
                    4
                )
            )
        )
    )
) * 0.15
